19	// decodeAggregateResults parses emitted lines back into AggregateResult so the
20	// assertions observe the exact signed 64-bit start/end/count/sum values.
21	func decodeAggregateResults(t *testing.T, stdout string) []AggregateResult {
22		t.Helper()
23		if stdout == "" {
24			return nil
25		}
26		var got []AggregateResult
27		for i, line := range strings.Split(strings.TrimSuffix(stdout, "\n"), "\n") {
28			var r AggregateResult
29			if err := json.Unmarshal([]byte(line), &r); err != nil {
30				t.Fatalf("invalid output line %d %q: %v", i+1, line, err)
31			}
