37	// The spec's large-number example: M=math.MaxInt64, window length 7, slide 4
38	// (not a divisor). Events at M-5 (value 2) and M-4 (value 3). Each event is
39	// counted once in every window that contains it, with the full value added;
40	// the second event sits exactly on the right edge of [M-11,M-4) and therefore
41	// enters only the later [M-7,M) window. A watermark strictly below a window
42	// end closes nothing; equality is what emits. An end exactly equal to M is a
43	// legal, representable window end and must not be reported as overflow.
44	func TestAggregateSlidingBigTimeWindowEndAtMaxInt64(t *testing.T) {
45		const M = math.MaxInt64
46		const w, sl int64 = 7, 4
47	
48		events := strings.Join([]string{
49			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":2}`, M-5),
50			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":3}`, M-4),
51		}, "\n")
52	
53		// Watermark M-5 is still strictly below the earliest window end M-4.
54		stdout, stderr, err := runSliding(t, events+"\n"+
55			fmt.Sprintf(`{"type":"watermark","time":%d}`, M-5), w, sl)
56		if err != nil {
57			t.Fatalf("unexpected error: %v", err)
58		}
59		if stderr != "" {
60			t.Fatalf("unexpected stderr: %q", stderr)
61		}
62		if stdout != "" {
63			t.Fatalf("watermark below the window end must close nothing, got %q", stdout)
64		}
65	
66		// Watermark M-4 closes [M-11,M-4); watermark M closes [M-7,M), whose end
67		// is exactly the largest representable signed 64-bit integer.
68		input := events + "\n" + strings.Join([]string{
69			fmt.Sprintf(`{"type":"watermark","time":%d}`, M-5),
70			fmt.Sprintf(`{"type":"watermark","time":%d}`, M-4),
71			fmt.Sprintf(`{"type":"watermark","time":%d}`, M),
72		}, "\n")
73		stdout, stderr, err = runSliding(t, input, w, sl)
74		if err != nil {
75			t.Fatalf("unexpected error: %v", err)
76		}
77		if stderr != "" {
78			t.Fatalf("unexpected stderr: %q", stderr)
