83			M-11, M-4, M-7, M)
84		if stdout != want {
85			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
86		}
87	
88		// Parse the integer fields back: both window bounds must survive as exact
89		// signed 64-bit values with no precision loss or sign flip.
90		got := decodeAggregateResults(t, stdout)
91		wantRows := []AggregateResult{
92			{Key: "k", Start: M - 11, End: M - 4, Count: 1, Sum: 2},
93			{Key: "k", Start: M - 7, End: M, Count: 2, Sum: 5},
94		}
95		if len(got) != len(wantRows) {
96			t.Fatalf("got %d rows, want %d: %v", len(got), len(wantRows), got)
97		}
98		for i := range wantRows {
99			if got[i] != wantRows[i] {
100				t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
101			}
102		}
103	}
104	
105	// With a window length of math.MaxInt64 and a short slide, events near time
106	// zero belong only to the window starting at zero. No negative-start window
107	// may be generated, and the [0,MaxInt64) window must not be dropped; its end
108	// is exactly MaxInt64 and closes at a watermark equal to it.
109	func TestAggregateSlidingBigWindowLengthNoNegativeStarts(t *testing.T) {
110		const M = math.MaxInt64
111		input := strings.Join([]string{
112			`{"type":"event","key":"k","time":0,"value":5}`,
113			`{"type":"event","key":"k","time":3,"value":7}`,
114			fmt.Sprintf(`{"type":"watermark","time":%d}`, M),
115		}, "\n")
116		stdout, stderr, err := runSliding(t, input, M, 4)
117		if err != nil {
118			t.Fatalf("unexpected error: %v", err)
119		}
120		if stderr != "" {
121			t.Fatalf("unexpected stderr: %q", stderr)
122		}
123		// Exactly one row proves the clamp at start zero: without it, grids such
124		// as [-4,MaxInt64-4) would also contain these events and close here,
125		// producing extra rows and double counting.
126		want := fmt.Sprintf(`{"key":"k","start":0,"end":%d,"count":2,"sum":12}`+"\n", M)
127		if stdout != want {
128			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
129		}
130		got := decodeAggregateResults(t, stdout)
131		if len(got) != 1 || got[0] != (AggregateResult{Key: "k", Start: 0, End: M, Count: 2, Sum: 12}) {
132			t.Fatalf("decoded rows = %v", got)
133		}
