136	// While the watermark is still below M-3, an event at M-3 (window length 7,
137	// slide 4) falls into both a representable window [M-7,M) and one whose end
138	// overflows [M-3,M+4). The whole input line must fail fatally: the error
139	// carries the physical line number (blank lines still count), says "window
140	// end overflow" and names the earliest offending start M-3. Output already
141	// written stays, the rejected event updates no window, and a later watermark
142	// is never processed.
143	func TestAggregateSlidingBigTimeWindowEndOverflowFatal(t *testing.T) {
144		const M = math.MaxInt64
145		const w, sl int64 = 7, 4
146		input := strings.Join([]string{
147			``, // line 1 blank: physical line numbers still count it
148			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":2}`, M-5),
149			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":3}`, M-4),
150			fmt.Sprintf(`{"type":"watermark","time":%d}`, M-4), // line 4 closes [M-11,M-4)
151			``, // line 5 blank
152			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":9}`, M-3), // line 6 fatal
153			fmt.Sprintf(`{"type":"watermark","time":%d}`, M),                   // line 7 must never be processed
154		}, "\n")
155		stdout, _, err := runSliding(t, input, w, sl)
156		if err == nil {
157			t.Fatal("expected window end overflow error, got nil")
158		}
159		inputErr, ok := err.(*InputError)
