161			t.Fatalf("expected *InputError, got %T: %v", err, err)
162		}
163		if inputErr.Line != 6 {
164			t.Errorf("line = %d, want 6 (blank lines must count)", inputErr.Line)
165		}
166		if !strings.Contains(inputErr.Reason, "window end overflow") {
167			t.Fatalf("reason = %q, want window end overflow", inputErr.Reason)
168		}
169		wantStart := fmt.Sprintf("window starting at %d with length %d", M-3, w)
170		if !strings.Contains(inputErr.Reason, wantStart) {
171			t.Fatalf("reason = %q, want it to name %s", inputErr.Reason, wantStart)
172		}
