174		if strings.Contains(inputErr.Reason, fmt.Sprintf("starting at %d", M-7)) {
175			t.Errorf("reason must not blame the fitting window start %d: %q", M-7, inputErr.Reason)
176		}
177		// Prior output is retained exactly; the post-error watermark never runs,
178		// so [M-7,M) must not appear even though M would close it.
179		want := fmt.Sprintf(`{"key":"k","start":%d,"end":%d,"count":1,"sum":2}`+"\n", M-11, M-4)
180		if stdout != want {
181			t.Fatalf("existing output must be retained with nothing added:\n got: %q\nwant: %q", stdout, want)
182		}
183	}
184	
185	// At the big boundary, slide equal to the window length must stay exactly
186	// identical to RunAggregate's fixed-window behavior: a legal end at
187	// math.MaxInt64 succeeds through both entry points, and a window end past
