91	// Legal values above 2^53 must not lose precision: 2^53+1 is not exactly
92	// representable as a float64, so any float round-trip in the sum path would
93	// print 9007199254740992 and 18014398509481984 instead of the true values.
94	func TestAggregateSlidingSumPrecisionAbove2To53(t *testing.T) {
95		input := strings.Join([]string{
96			`{"type":"event","key":"k","time":100,"value":9007199254740993}`, // 2^53+1
97			`{"type":"event","key":"k","time":700,"value":9007199254740993}`, // shared by both windows
98			`{"type":"watermark","time":1600}`,
99		}, "\n")
100		stdout, stderr, err := runSliding(t, input, 1000, 600)
101		if err != nil {
102			t.Fatalf("unexpected error: %v", err)
103		}
