189			`{"type":"event","key":"k","time":1300,"value":9223372036854775807}`,
190			`{"type":"event","key":"k","time":1000,"value":1}`, // line 5 fatal
191			`{"type":"watermark","time":2200}`,                 // line 6 must never be processed
192		}, "\n")
