194		if err == nil {
195			t.Fatal("expected cumulative sum overflow, got nil")
196		}
197		inputErr, ok := err.(*InputError)
198		if !ok {
199			t.Fatalf("expected *InputError, got %T: %v", err, err)
200		}
201		if inputErr.Line != 5 {
202			t.Errorf("line = %d, want 5 (blank lines must count)", inputErr.Line)
203		}
204		if !strings.Contains(inputErr.Reason, "cumulative sum overflow") {
205			t.Fatalf("reason = %q, want cumulative sum overflow", inputErr.Reason)
206		}
207		if !strings.Contains(inputErr.Reason, `for key "k"`) {
208			t.Fatalf("reason = %q, want it to name the key", inputErr.Reason)
209		}
210		if !strings.Contains(inputErr.Reason, "window [600,1600)") {
211			t.Fatalf("reason = %q, want it to name the overflowing window [600,1600)", inputErr.Reason)
212		}
213		if !strings.Contains(inputErr.Reason, "9223372036854775807 + 1") {
214			t.Fatalf("reason = %q, want it to show the overflowing addition", inputErr.Reason)
215		}
216		// [300,1300) accepted this same event safely; it is not the offender.
217		if strings.Contains(inputErr.Reason, "[300,1300)") {
218			t.Errorf("reason must not blame the safe window [300,1300): %q", inputErr.Reason)
219		}
220		// The result closed before the failure stays; the post-error watermark
221		// never runs, so no further window is emitted.
222		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":7}` + "\n"
223		if stdout != want {
224			t.Fatalf("existing output must be retained with nothing added:\n got: %q\nwant: %q", stdout, want)
225		}
226	}
227	
228	// Mirror image at the negative boundary: the later window already sits at
229	// MinInt64, so the same event that the earlier window accepts drives it
230	// below the limit. The error names the truly overflowing window and shows
231	// the exact addition.
232	func TestAggregateSlidingSumUnderflowNamesOverflowingWindow(t *testing.T) {
233		input := strings.Join([]string{
234			`{"type":"event","key":"k","time":1300,"value":-9223372036854775808}`,
235			`{"type":"event","key":"k","time":1000,"value":-1}`, // line 2 fatal
236			`{"type":"watermark","time":2200}`,                  // never processed
237		}, "\n")
238		stdout, _, err := runSliding(t, input, 1000, 300)
239		if err == nil {
240			t.Fatal("expected cumulative sum overflow, got nil")
241		}
242		inputErr, ok := err.(*InputError)
243		if !ok {
244			t.Fatalf("expected *InputError, got %T: %v", err, err)
245		}
246		if inputErr.Line != 2 {
247			t.Errorf("line = %d, want 2", inputErr.Line)
248		}
249		if !strings.Contains(inputErr.Reason, "cumulative sum overflow") {
250			t.Fatalf("reason = %q, want cumulative sum overflow", inputErr.Reason)
251		}
252		if !strings.Contains(inputErr.Reason, "window [600,1600)") {
253			t.Fatalf("reason = %q, want it to name the overflowing window [600,1600)", inputErr.Reason)
254		}
255		if !strings.Contains(inputErr.Reason, "-9223372036854775808 + -1") {
256			t.Fatalf("reason = %q, want it to show the overflowing addition", inputErr.Reason)
257		}
258		if strings.Contains(inputErr.Reason, "[300,1300)") {
259			t.Errorf("reason must not blame the safe window [300,1300): %q", inputErr.Reason)
260		}
261		if stdout != "" {
262			t.Fatalf("no window closed before the failure, got %q", stdout)
263		}
264	}
265	
266	// Overflow is judged at the moment of the addition, not from the final
267	// total: MaxInt64 + 1 overflows at line 2 even though the value -1 on line 3
268	// would bring the sum back into range. The cancelling event and the closing
269	// watermark after the failure are never processed.
270	func TestAggregateSlidingSumOverflowNotMaskedByLaterEvents(t *testing.T) {
271		input := strings.Join([]string{
272			`{"type":"event","key":"k","time":700,"value":9223372036854775807}`,
273			`{"type":"event","key":"k","time":800,"value":1}`, // line 2: MaxInt64 + 1 overflows
274			`{"type":"event","key":"k","time":900,"value":-1}`,
275			`{"type":"watermark","time":1600}`,
276		}, "\n")
277		stdout, _, err := runSliding(t, input, 1000, 600)
278		if err == nil {
279			t.Fatal("expected cumulative sum overflow, got nil")
280		}
281		inputErr, ok := err.(*InputError)
282		if !ok {
283			t.Fatalf("expected *InputError, got %T: %v", err, err)
284		}
285		if inputErr.Line != 2 {
286			t.Errorf("line = %d, want 2", inputErr.Line)
287		}
288		if !strings.Contains(inputErr.Reason, "sum overflow") {
289			t.Fatalf("reason = %q, want sum overflow", inputErr.Reason)
290		}
291		if stdout != "" {
292			t.Fatalf("nothing may be emitted after the mid-stream overflow, got %q", stdout)
293		}
294	}
295	
296	// A late event is only skipped with a notice, even when its value would
297	// overflow the still-open window it falls into: it changes no sum and never
298	// becomes a cumulative sum error. The window keeps accumulating later valid
299	// events and closes with the exact boundary sum.
300	func TestAggregateSlidingLateEventOverflowValueSkipped(t *testing.T) {
301		input := strings.Join([]string{
302			`{"type":"event","key":"k","time":700,"value":9223372036854775807}`,
303			`{"type":"watermark","time":1000}`, // closes [0,1000); [600,1600) stays open
304			`{"type":"event","key":"k","time":999,"value":9223372036854775807}`, // line 3: late; would overflow [600,1600)
305			`{"type":"event","key":"k","time":1000,"value":-5}`,                 // valid: joins [600,1600)
306			`{"type":"watermark","time":1600}`,
307		}, "\n")
308		stdout, stderr, err := runSliding(t, input, 1000, 600)
309		if err != nil {
310			t.Fatalf("late event must not become a sum error, got: %v", err)
311		}
312		wantErr := "line 3: late event time=999 below current watermark 1000, skipped\n"
313		if stderr != wantErr {
314			t.Fatalf("stderr = %q, want %q", stderr, wantErr)
315		}
316		want := strings.Join([]string{
317			`{"key":"k","start":0,"end":1000,"count":1,"sum":9223372036854775807}`,
318			// The skipped late event contributed nothing: MaxInt64 - 5.
319			`{"key":"k","start":600,"end":1600,"count":2,"sum":9223372036854775802}`,
320			``,
321		}, "\n")
322		if stdout != want {
323			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
324		}
325	}
326	
327	// The overflow error identifies the exact window and addition for every
328	// containing-window grid, not just one slide: with window 1200, slide 400
329	// the event at 1000 belongs to [0,1200),[400,1600),[800,1800) and only the
330	// windows already holding MaxInt64 may be named.
331	func TestAggregateSlidingSumOverflowGridVariants(t *testing.T) {
332		const M = math.MaxInt64
333		input := strings.Join([]string{
334			fmt.Sprintf(`{"type":"event","key":"k","time":1400,"value":%d}`, M),
335			`{"type":"event","key":"k","time":1000,"value":1}`,
336		}, "\n")
337		// t=1400 belongs to [400,1600),[800,1800),[1200,2200); t=1000 belongs to
338		// [0,1200),[400,1600),[800,1800). The shared windows [400,1600) and
339		// [800,1800) hold MaxInt64; [0,1200) is empty and accepts the event.
340		_, _, err := runSliding(t, input, 1200, 400)
341		if err == nil {
342			t.Fatal("expected cumulative sum overflow, got nil")
343		}
344		inputErr, ok := err.(*InputError)
345		if !ok {
346			t.Fatalf("expected *InputError, got %T: %v", err, err)
347		}
348		if inputErr.Line != 2 {
349			t.Errorf("line = %d, want 2", inputErr.Line)
350		}
351		if !strings.Contains(inputErr.Reason, "window [400,1600)") {
352			t.Fatalf("reason = %q, want it to name the first overflowing window [400,1600)", inputErr.Reason)
353		}
354		if strings.Contains(inputErr.Reason, "[0,1200)") {
355			t.Errorf("reason must not blame the safe window [0,1200): %q", inputErr.Reason)
356		}
357	}
