// A merged result may appear only once the effective watermark reaches the
// window end. Partition 0 races ahead and partitions 1 lags; the windows that
// hold both partitions' boundary-near contributions stay closed by the min,
// even while p0's own watermark is already past their ends. Advancing p1
// finally emits them, with each event contributing once per containing
// window.
func TestAggregatePartitionedSlidingSumWaitsForEffectiveWatermark(t *testing.T) {
	input := strings.Join([]string{
		// Shared windows [600,1600) and [1200,2200); each event sits in both.
		`{"type":"event","key":"k","time":700,"value":4000000000000000000,"partition":0}`,
		`{"type":"event","key":"k","time":1300,"value":4000000000000000000,"partition":1}`, // merged sum = 8e18, legal
		`{"type":"watermark","time":5000,"partition":0}`, // fast partition: nothing may close yet
		`{"type":"watermark","time":1600,"partition":1}`,  // min = 1600: closes [600,1600) only
		`{"type":"watermark","time":2200,"partition":1}`,  // min = 2200: closes [1200,2200)
	}, "\n")
	stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("unexpected stderr: %q", stderr)
	}
	// Crucially, nothing appeared right after the fast partition's watermark
	// (line 3): the same input truncated there must emit nothing at all.
	prefix := strings.Join([]string{
		`{"type":"event","key":"k","time":700,"value":4000000000000000000,"partition":0}`,
		`{"type":"event","key":"k","time":1300,"value":4000000000000000000,"partition":1}`,
		`{"type":"watermark","time":5000,"partition":0}`,
	}, "\n")
	if early, _, err := runPartitionedSliding(t, prefix, 1000, 600, 2); err != nil {
		t.Fatalf("prefix run error: %v", err)
	} else if early != "" {
		t.Fatalf("one fast partition must not close windows ahead of the other, got %q", early)
	}

	want := strings.Join([]string{
		`{"key":"k","start":600,"end":1600,"count":2,"sum":8000000000000000000}`,
		`{"key":"k","start":1200,"end":2200,"count":2,"sum":8000000000000000000}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

// Positive boundary across partitions: an earlier window already holds a
// legal merged MaxInt64 (and has been published by the effective watermark);
// the other partition's next event is still legal in that earlier window but
// pushes the later shared window over the upper bound. The run fails at that
// event's physical line, naming only the window that actually overflows and
// showing its accumulated value plus the incoming one. Blank lines count.
func TestAggregatePartitionedSlidingSumOverflowNamesOverflowingWindow(t *testing.T) {
	input := strings.Join([]string{
		``, // line 1 blank: physical line numbers still count it
		// p0 saturates both windows containing t=1300: [600,1600), [900,1900),
		// [1200,2200) (window 1000, slide 300).
		fmtEvt("k", 1300, math.MaxInt64, 0),
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"watermark","time":1600,"partition":1}`, // line 4 closes [600,1600) at MaxInt64
		``,                                              // line 5 blank
		// p1 event at 1000 belongs to [300,1300), [600,1600), [900,1900):
		// [300,1300) is empty and accepts it; [900,1900) already holds MaxInt64
		// and is the earliest window this line overflows.
		fmtEvt("k", 1000, 1, 1), // line 6 fatal
		`{"type":"watermark","time":5000,"partition":1}`,
		`{"type":"watermark","time":5000,"partition":0}`,
	}, "\n")
	stdout, stderr, err := runPartitionedSliding(t, input, 1000, 300, 2)
	if err == nil {
		t.Fatal("expected cumulative sum overflow, got nil")
	}
	inputErr, ok := err.(*InputError)
	if !ok {
		t.Fatalf("expected *InputError, got %T: %v", err, err)
	}
	if inputErr.Line != 6 {
		t.Errorf("line = %d, want 6 (blank lines must count)", inputErr.Line)
	}
	if !strings.Contains(inputErr.Reason, "cumulative sum overflow") {
		t.Fatalf("reason = %q, want cumulative sum overflow", inputErr.Reason)
	}
	if !strings.Contains(inputErr.Reason, `for key "k"`) {
		t.Fatalf("reason = %q, want it to name the key", inputErr.Reason)
	}
	if !strings.Contains(inputErr.Reason, "window [900,1900)") {
		t.Fatalf("reason = %q, want it to name the overflowing window [900,1900)", inputErr.Reason)
	}
	if !strings.Contains(inputErr.Reason, "9223372036854775807 + 1") {
		t.Fatalf("reason = %q, want it to show accumulated value and new value", inputErr.Reason)
	}
	// This same event was legal in the earlier window and closed windows must
	// not be listed as the cause.
	for _, safe := range []string{"[300,1300)", "[600,1600)"} {
		if strings.Contains(inputErr.Reason, safe) {
			t.Errorf("reason must not blame the non-overflowing window %s: %q", safe, inputErr.Reason)
		}
	}
	// The already-closed [600,1600) result stays exactly as published; after
	// the failure no further partition event or watermark takes effect, so
	// [900,1900) (closed at 1900) and [1200,2200) never appear.
	want := `{"key":"k","start":600,"end":1600,"count":1,"sum":9223372036854775807}` + "\n"
	if stdout != want {
		t.Fatalf("closed output must be retained with nothing added:\n got: %q\nwant: %q", stdout, want)
	}
	if stderr != "" {
		t.Fatalf("every event time is >= the effective watermark; late log must stay empty, got %q", stderr)
	}
}

// Mirror image at the negative boundary with the partitions swapped: the
// earlier window accepts the other partition's negative event, while the
// shared later window is already at MinInt64. The error names the earliest
// window that actually underflows and shows the exact addition.
func TestAggregatePartitionedSlidingSumUnderflowNamesOverflowingWindow(t *testing.T) {
	input := strings.Join([]string{
		fmtEvt("k", 1300, math.MinInt64, 1), // p1 saturates [600,1600),[900,1900),[1200,2200)
		fmtEvt("k", 1000, -1, 0),             // line 2: legal in [300,1300), underflows [900,1900)
		`{"type":"watermark","time":5000,"partition":0}`,
		`{"type":"watermark","time":5000,"partition":1}`,
	}, "\n")
	stdout, stderr, err := runPartitionedSliding(t, input, 1000, 300, 2)
	if err == nil {
		t.Fatal("expected cumulative sum overflow, got nil")
	}
	inputErr, ok := err.(*InputError)
	if !ok {
		t.Fatalf("expected *InputError, got %T: %v", err, err)
	}
	if inputErr.Line != 2 {
		t.Errorf("line = %d, want 2", inputErr.Line)
	}
	if !strings.Contains(inputErr.Reason, "cumulative sum overflow") {
		t.Fatalf("reason = %q, want cumulative sum overflow", inputErr.Reason)
	}
	if !strings.Contains(inputErr.Reason, "window [900,1900)") {
		t.Fatalf("reason = %q, want it to name the overflowing window [900,1900)", inputErr.Reason)
	}
	if !strings.Contains(inputErr.Reason, "-9223372036854775808 + -1") {
		t.Fatalf("reason = %q, want it to show accumulated value and new value", inputErr.Reason)
	}
	if strings.Contains(inputErr.Reason, "[300,1300)") {
		t.Errorf("reason must not blame the safe window [300,1300): %q", inputErr.Reason)
	}
	if stdout != "" || stderr != "" {
		t.Fatalf("nothing may be emitted or logged after the immediate failure, got stdout=%q stderr=%q", stdout, stderr)
	}
}

// Overflow is judged at the addition that crosses the boundary, not from the
// eventual mathematical total: a later opposite-sign event from the other
// partition would bring the window sum back into range, but it can never
// erase the overflow that already happened. Neither that event nor any
// following watermark is processed, so no open window is published.
func TestAggregatePartitionedSlidingSumOverflowNotMaskedByLaterEvents(t *testing.T) {
	input := strings.Join([]string{
		fmtEvt("k", 700, math.MaxInt64, 0),
		fmtEvt("k", 800, 1, 1),  // line 2: merged MaxInt64 + 1 overflows both shared windows
		fmtEvt("k", 900, -1, 0), // would cancel it: never processed
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"watermark","time":1600,"partition":1}`,
	}, "\n")
	stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
	if err == nil {
		t.Fatal("expected cumulative sum overflow, got nil")
	}
	inputErr, ok := err.(*InputError)
	if !ok {
		t.Fatalf("expected *InputError, got %T: %v", err, err)
	}
	if inputErr.Line != 2 {
		t.Errorf("line = %d, want 2", inputErr.Line)
	}
	if !strings.Contains(inputErr.Reason, "cumulative sum overflow") {
		t.Fatalf("reason = %q, want cumulative sum overflow", inputErr.Reason)
	}
	// Earliest containing window of the t=800 event is [0,1000); that is the
	// first addition that crosses, so it is the window named.
	if !strings.Contains(inputErr.Reason, "window [0,1000)") {
		t.Fatalf("reason = %q, want it to name the first overflowing window [0,1000)", inputErr.Reason)
	}
	if stdout != "" {
		t.Fatalf("no window had closed before the failure; nothing may be emitted, got %q", stdout)
	}
	if stderr != "" {
		t.Fatalf("late log must stay empty for non-late events, got %q", stderr)
	}
}

// fmtEvt renders one partitioned event record.
func fmtEvt(key string, time, value, partition int64) string {
	return `{"type":"event","key":"` + key + `","time":` +
		strings.TrimSpace(itoa64(time)) + `,"value":` + itoa64(value) +
		`,"partition":` + itoa64(partition) + `}`
}

// itoa64 formats a signed 64-bit integer without pulling in strconv just for
// the builder above.
func itoa64(v int64) string {
	neg := v < 0
	u := uint64(v)
	if neg {
		u = uint64(-v)
	}
	var buf [20]byte
	i := len(buf)
	if u == 0 {
		i--
		buf[i] = '0'
	}
	for u > 0 {
		i--
		buf[i] = byte('0' + u%10)
		u /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

