		fmtEvt("k", 1300, math.MinInt64, 1), // p1 saturates [600,1600),[900,1900),[1200,2200)
		fmtEvt("k", 1000, -1, 0),             // line 2: legal in [300,1300), underflows [900,1900)
		`{"type":"watermark","time":5000,"partition":0}`,
		`{"type":"watermark","time":5000,"partition":1}`,
	}, "\n")
