		fmt.Sprintf(`{"key":"k","start":1200,"end":2200,"count":1,"sum":%d}`, big), // p1 only
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

